const input = $input.first();
const headers = input.json.headers ?? {};
const body = input.json.body ?? {};
const binary = input.binary ?? {};
const fileKey = binary.file ? 'file' : binary.data ? 'data' : Object.keys(binary)[0];

if (!fileKey || !binary[fileKey]) {
  throw new Error('No file received. Send multipart/form-data with a field named file.');
}

const uploadedFile = binary[fileKey];
const fileName = uploadedFile.fileName ?? 'dataset.csv';
const extension = fileName.split('.').pop()?.toLowerCase();
const allowedExtensions = ['csv', 'xlsx', 'xls'];

if (!extension || !allowedExtensions.includes(extension)) {
  throw new Error(`Unsupported file type: ${extension ?? 'unknown'}. Use CSV, XLSX, or XLS.`);
}

const authorization = headers.authorization ?? headers.Authorization;
if (!authorization || !authorization.startsWith('Bearer ')) {
  throw new Error('Missing Quantura Authorization header. Use Bearer followed by a valid Quantura access token.');
}

const fallbackName = fileName.replace(/\.[^.]+$/, '');
const requestedName = String(body.name ?? body.project_name ?? fallbackName).trim();
const datasetName = requestedName.slice(0, 120) || fallbackName;

return [{
  json: {
    authorization,
    dataset_name: datasetName,
    original_filename: fileName,
    received_at: new Date().toISOString()
  },
  binary: {
    file: uploadedFile
  }
}];
